int minFlips(int a, int b, int c) {
    int flips = 0;
    for (int i = 0; i < 31; ++i) {
        int x = (a >> i) & 1, y = (b >> i) & 1, z = (c >> i) & 1;
        if (z == 0) flips += x + y;                       // both must be cleared
        else if (x == 0 && y == 0) flips += 1;            // one of them must be set
    }
    return flips;
}

public int minFlips(int a, int b, int c) {
    int flips = 0;
    for (int i = 0; i < 31; i++) {
        int x = (a >> i) & 1, y = (b >> i) & 1, z = (c >> i) & 1;
        if (z == 0) flips += x + y;                       // both must be cleared
        else if (x == 0 && y == 0) flips += 1;            // one of them must be set
    }
    return flips;
}
